def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def get_any(obj, keys, default=None):
        if isinstance(obj, dict):
            for k in keys:
                if k in obj:
                    return obj.get(k)
        return default

    def as_pos(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            return x[0], x[1]
        return None

    def find_self_pos(obs):
        cand = [
            get_any(obs, ("agent_pos", "self_pos", "position", "pos", "player_pos")),
            get_any(obs, ("agent", "self", "player")),
        ]
        for c in cand:
            p = as_pos(c)
            if p is not None:
                return p
            if isinstance(c, dict):
                p = as_pos(get_any(c, ("pos", "position", "loc", "location")))
                if p is not None:
                    return p

        entities = get_any(obs, ("entities", "units", "agents", "players"), [])
        if isinstance(entities, dict):
            for v in entities.values():
                if isinstance(v, dict) and v.get("self", False):
                    p = as_pos(get_any(v, ("pos", "position", "loc", "location")))
                    if p is not None:
                        return p
        if isinstance(entities, (list, tuple)):
            for e in entities:
                if isinstance(e, dict) and e.get("self", False):
                    p = as_pos(get_any(e, ("pos", "position", "loc", "location")))
                    if p is not None:
                        return p

        return (0, 0)

    def normalize_points(obj):
        pts = []
        if obj is None:
            return pts
        if isinstance(obj, dict):
            for v in obj.values():
                p = as_pos(v)
                if p is not None:
                    pts.append(p)
