                elif isinstance(v, dict):
                    p = as_pos(get_any(v, ("pos", "position", "loc", "location", "target")))
                    if p is not None:
                        pts.append(p)
        return pts

    def nearest(src, points):
        if not points:
            return None
        sx, sy = src
        best = None
        best_d = None
        for px, py in points:
            d = abs(px - sx) + abs(py - sy)
            if best_d is None or d < best_d:
