                best = (px, py)
        return best

    def choose_toward(src, dst):
        if dst is None:
            return [0, 0]
        sx, sy = src
        dx, dy = dst
        return [clamp_step(dx - sx), clamp_step(dy - sy)]

    me = find_self_pos(observation)
